import {ToolRegistry} from './registry.js';

// @spec specs/hal-engine-tool-input-validation/spec.md#2
it('names the location type constraint without exposing the rejected number', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Weather lookup',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}},
    },
    async () => {
      throw new Error('Executor received invalid input');
    }
  );

  const response = await registry.execute('weather', {location: 8675309});
  expect(response.result).toMatch(/location.*type.*string/);
  expect(response.result).not.toContain('8675309');
});
EOF
